INSERT INTO objeciones_linea_real (fuente_documento, codigo_tpsns, cantidad, valor_unitario, valor_solicitado, valor_objetado, valor_aprobado, fue_objetado, motivo_texto, identificador_anonimo) VALUES ('EMR-07-DER', 99282, 1, 13.4, 13.4, 13.4, 0, True, 'SIN OBJECION | No se reconoce y se mantiene la objeción, dado que el TPSNS únicamente reconoce la atención brindada por médicos especialistas. El error en el planillaje del prestador, al no solicitar el cubículo de emergencia, no justifica el cobro de honorarios por la atención realizada por un médico residente. Asimismo, el TPSNS señala expresamente: “Para médicos residentes propios del servicio y personal paramédico, en la realización de actividades de control de signos vitales, valoración de talla y peso, administración de medicamentos; no se reconocerán valores monetarios expresados en esta sección.” | SE APLICA OBJECION DE PERTINENCIA MEDICA', 31);
